function tryParsePort(raw: string): Result<number, 'empty' | 'nan' | 'range'> {
  if (!raw.trim()) return { ok: false, error: 'empty' };
  const n = Number(raw);
  if (Number.isNaN(n)) return { ok: false, error: 'nan' };
  if (n < 1 || n > 65535) return { ok: false, error: 'range' };
  return { ok: true, value: n };
}

